public static int getRandomAmount(int num, double chance) {

    if (chance >= 1.0D) {
      return num;
    } else if (chance <= 0.0D) {
      return 0;
    }
    int amount = 0;

    for (int i = 0; i < num; i++) {
      if (RAND.nextDouble() < chance) {
        amount++;
      }
    }
    return amount;
  }

