evidence.text:
private static int getExperiencePointsFromLevel(int levels) {
    int points = 0;

    if (levels <= 16) {
      points += levels * levels + 6 * levels;
    } else if (levels <= 31) {
      points += levels * levels * 2.5f - levels * 40.5f + 360;
    } else {
      points += levels * levels * 4.5f - levels * 162.5f + 2220;
    }
    return points;
  }

